using Oikonomis.Application;using Oikonomis.Domain;using Xunit;
namespace Oikonomis.UnitTests;public sealed class NormalizationTests{[Fact]public void Iban_is_uppercase_without_spaces()=>Assert.Equal("NL91ABNA0417164300",Normalization.Iban("nl91 abna 0417 1643 00"));[Fact]public void Remittance_collapses_whitespace()=>Assert.Equal("hello world",Normalization.Text(" hello  \r\n world "));[Fact]public void Fingerprint_is_stable(){var t=new ParsedTransaction("e","s",null,"z",null,null,new(2026,1,2),null,1.23m,"EUR",CreditDebitIndicator.Debit,null,null,null,null,"NL 12 TEST",null," invoice  1 ",null,"{}");Assert.Equal(Normalization.Fingerprint(Guid.Empty,t),Normalization.Fingerprint(Guid.Empty,t));}}
